/**
 * Creates a conservative .gitignore for projects installed with GD-KS.
 *
 * Only generated editor, operating-system, and engine build artifacts are
 * ignored. Source assets and GD-KS deliverables remain versioned by default.
 */
export class GitignoreGenerator {
  static generate(engine = 'unreal-5') {
    const sections = [
      '# Generated by GD-KS during installation',
      '# Keep source files, project settings, and _gdks-output/ under version control.',
      '',
      '# Operating system files',
      '.DS_Store',
      'Thumbs.db',
      'Desktop.ini',
      '',
      '# Editor and IDE files',
      '.idea/',
      '.vscode/*.log',
      ''
    ];

    const engineSections = {
      'godot-4': [
        '# Godot 4+ generated files',
        '.godot/',
        '/android/',
        '',
        '# C# / Mono build artifacts',
        '.mono/',
        'bin/',
        'obj/',
        '',
        '# Local game exports and packages',
        '/export/',
        '/exports/',
        '/build/',
        '/builds/',
        '*.pck',
        '*.apk',
        '*.aab',
        '*.ipa',
        ''
      ],
      'unreal-5': [
        '# Unreal Engine generated files',
        'Binaries/',
        'DerivedDataCache/',
        'Intermediate/',
        'Saved/',
        '.vs/',
        '*.sln',
        '*.suo',
        '*.xcodeproj',
        ''
      ],
      'unity-6': [
        '# Unity generated files',
        '[Ll]ibrary/',
        '[Tt]emp/',
        '[Oo]bj/',
        '[Bb]uild/',
        '[Bb]uilds/',
        '[Ll]ogs/',
        '[Uu]ser[Ss]ettings/',
        'MemoryCaptures/',
        'Recordings/',
        ''
      ],
      agnostic: [
        '# No engine-specific generated files for an engine-agnostic project',
        ''
      ]
    };

    return `${[...sections, ...(engineSections[engine] || engineSections.agnostic)].join('\n')}\n`;
  }
}
